INSERT INTO changelog (title, body, created_at) VALUES ('Meta: короткий токен більше не приймається', 'Система перевіряє строк дії токена Meta під час збереження. Короткий токен, який живе 1–2 години, не приймає і підказує, як його продовжити (debug/accesstoken → «Продовжити маркер доступу»). Після нового токена заявки одразу починають тягнутись, без паузи.', datetime('now'));
